  negb (c_ltu (v_srli (Z_to_bv 64 4096) 1) (v_addi (v_mul (Z_to_bv 64 (16 * szc)) (Z_to_bv 64 c1)) 16)) = (16 * szc * c1 + 16 <=? 2048).
