Lemma roundup_word16 : forall x, 0 <= x < 2^40 ->
  v_addi (v_add (Z_to_bv 64 x) (v_and (v_sub (wlit (2^64 - 16)) (Z_to_bv 64 x)) (v_addi (Z_to_bv 64 4096) (-1)))) 16
